// RestrictedMatchDisclosure is the per-source rule for a knowledge item that
// matched a question but that the requester cannot read. Without it, a
// permission-filtered miss and a genuine absence look identical to the agent
// (both are zero results), so the agent cannot say "this exists but you do not
// have access" and instead searches, fails, and improvises (DLB-609, DLB-592).
type RestrictedMatchDisclosure int32

const (
	RestrictedMatchDisclosure_RESTRICTED_MATCH_DISCLOSURE_UNSPECIFIED RestrictedMatchDisclosure = 0
	// Treat restricted items as if they do not exist. The agent answers only
	// from what the requester can read. Today's behaviour and the org default.
	RestrictedMatchDisclosure_RESTRICTED_MATCH_DISCLOSURE_SILENT RestrictedMatchDisclosure = 1
	// Tell the requester that restricted content matched, without titles or
	// links, and offer an access request.
	RestrictedMatchDisclosure_RESTRICTED_MATCH_DISCLOSURE_ACKNOWLEDGE RestrictedMatchDisclosure = 2
	// Show the item title and the source link; the source enforces access on
	// click. Content is never quoted. In a non-DM channel svflow degrades this
	// to ACKNOWLEDGE as a rule, not a setting.
	RestrictedMatchDisclosure_RESTRICTED_MATCH_DISCLOSURE_NAME_AND_LINK RestrictedMatchDisclosure = 3
)

