// How a revision stands relative to the article's live content. A revision is
// A PROPOSED change to an article is still a svmeta change set, and
// change_set_status owns pending / accepted / rejected / applying / applied /
// failed for the PROPOSAL. PENDING_APPROVAL and REJECTED below are a different
// question: not "is this redline any good" but "may this revision go live",
// and they exist only for a team that turned the publish gate on.
type KnowledgeDocumentVersionState int32

const (
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_UNSPECIFIED KnowledgeDocumentVersionState = 0
	// Live. This is what the agent answers from.
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_PUBLISHED KnowledgeDocumentVersionState = 1
	// A newer revision replaced it.
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_SUPERSEDED KnowledgeDocumentVersionState = 2
	// Withdrawn by an unpublish. No newer revision replaced it.
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_RETIRED KnowledgeDocumentVersionState = 3
	// Published while the team's approval gate was on. The snapshot exists but
	// is NOT live: the publish pointer stayed on the previously published
	// revision, so readers and the agent still see approved content.
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_PENDING_APPROVAL KnowledgeDocumentVersionState = 4
	// An approver refused it. Terminal — nothing revives a rejected revision;
	// the author edits the draft and publishes again, which mints a new one.
	KnowledgeDocumentVersionState_KNOWLEDGE_DOCUMENT_VERSION_STATE_REJECTED KnowledgeDocumentVersionState = 5
)

